const raw = $input.item.json.choices?.[0]?.message?.content || '{}';
let tema;
try { tema = JSON.parse(raw); }
catch(e) {
  const m = raw.match(/\{[\s\S]*?\}/);
  try { tema = m ? JSON.parse(m[0]) : {}; } catch(e2) { tema = {}; }
}
return [{ json: {
  trend_topic:    tema.topic         || '',
  trend_keyword:  tema.keyword       || '',
  trend_justify:  tema.justificacion || '',
  trend_platform: tema.plataforma    || 'Instagram'
}}];

const parsed = $('🔍 Parsear Estrategia').item.json;
const trend  = $('✅ Evaluar Verificación Tendencia').item.json;
const company_id = $('⚙️ Config G54').item.json.G54_COMPANY_ID || 1;

const ideasPlan = parsed.ideas_plan || [];
const frecSemanal = Number($('⚙️ Config G54').item.json.G54_FRECUENCIA_SEMANAL) || 3;
const generalesPorSemana = Math.max(1, frecSemanal - 1);

// Agrupar ideas por semana, tomar N-1 por semana
const semanas = {};
for (const idea of ideasPlan) {
  const s = idea.semana || 1;
  if (!semanas[s]) semanas[s] = [];
  if (semanas[s].length < generalesPorSemana) {
    semanas[s].push({
      topic:        idea.titulo || idea.topic || '',
      tipo:         idea.tipo   || 'TOFU',
      keyword:      idea.keyword || '',
      plataforma:   idea.plataforma || 'Instagram',
      semana:       s,
      dia:          idea.dia || '',
      estado:       'pendiente',
      es_tendencia: false
    });
  }
}

// Si no hay ideas del plan, crear semanas vacías para al menos poner la tendencia
if (Object.keys(semanas).length === 0) {
  semanas[1] = [];
}

// Agregar 1 idea de tendencia por semana
for (const s of Object.keys(semanas)) {
  if (trend.trend_topic) {
    semanas[s].push({
      topic:         trend.trend_topic,
      tipo:          'TOFU',
      keyword:       trend.trend_keyword || '',
      plataforma:    trend.trend_platform || 'Instagram',
      semana:        Number(s),
      dia:           'viernes',
      estado:        'pendiente',
      es_tendencia:  true,
      justificacion: trend.trend_justify || ''
    });
  }
}

const ideas = Object.values(semanas).flat();
if (ideas.length === 0) return [{ json: { skipped: true } }];

return [{ json: { company_id: Number(company_id), ideas } }];

// Extract titles from NewsAPI JSON response
const resp = $input.item.json;

const articles = resp.articles || [];
const titles = articles
  .filter(a => a.title && a.title !== '[Removed]')
  .slice(0, 8)
  .map((a, i) => `${i+1}. ${a.title} (${a.source?.name || ''})`);

const summary = titles.length > 0
  ? titles.join('\n')
  : 'No recent news found.';

return [{ json: {
  headlines: summary,
  count: titles.length
}}];

// Build English search query from company data
const empresa = $('🏢 Obtener Empresa G54').item.json.data;
const industry = (empresa.industry || '').toLowerCase();
const city = (empresa.base_city || '').split('/')[1]?.trim() || empresa.base_city || '';

// Map known industry terms to English search queries
const industryMap = {
  'embalaje': 'industrial packaging OR wooden crates OR crating',
  'crating': 'industrial crating OR wooden crates OR industrial packaging',
  'packaging': 'industrial packaging OR wooden crates',
  'logistic': 'logistics OR freight OR supply chain',
  'transport': 'freight transport OR logistics',
  'construction': 'construction industry OR building materials',
  'food': 'food industry OR food packaging',
  'tech': 'technology industry OR tech innovation',
};

let query = 'industrial packaging OR wooden crates OR crating'; // default
for (const [key, val] of Object.entries(industryMap)) {
  if (industry.includes(key)) {
    query = val;
    break;
  }
}

return [{ json: { newsapi_query: query } }];

const tema = $('🔍 Parsear Tema Tendencia').item.json;
const verif = $input.item.json;

const totalResults = verif.totalResults || 0;
const THRESHOLD = 5; // mínimo artículos en últimos 3 días para confirmar tendencia

const esVerificada = tema.trend_topic && totalResults >= THRESHOLD;

return [{ json: {
  trend_topic:     tema.trend_topic,
  trend_keyword:   tema.trend_keyword,
  trend_justify:   tema.trend_justify,
  trend_platform:  tema.trend_platform,
  es_tendencia:    esVerificada,
  trend_verificada: esVerificada,
  trend_articulos_recientes: totalResults,
  trend_nota: esVerificada
    ? `Verificada: ${totalResults} artículos en últimos 3 días`
    : `No verificada: solo ${totalResults} artículos recientes (mínimo ${THRESHOLD})`
}}];

const cfg      = $('⚙️ Config G54').item.json;
const empRaw   = $('🏢 Obtener Empresa G54').item.json;
const prodRaw  = $('📦 Obtener Productos G54').item.json;
const kwRaw    = $('🔍 Obtener Keywords G54').item.json;

const emp   = empRaw.data  || empRaw  || {};
const prods = prodRaw.data || prodRaw || [];
const allKw = (kwRaw.data  || kwRaw   || []).filter(k => k.estado === 'activa');

// Parámetros del plan — leer desde G54 config del cliente (con fallback a Config G54)
let tiempo_horizonte   = cfg.G54_PLAN_HORIZONTE      || '3 meses';
let frecuencia_semanal = Number(cfg.G54_FRECUENCIA_SEMANAL) || 3;
try {
  const rrssConfig = $('⚙️ Config RRSS Cliente G54').item.json;
  if (rrssConfig && rrssConfig.data) {
    if (rrssConfig.data.horizonte)          tiempo_horizonte   = rrssConfig.data.horizonte;
    if (rrssConfig.data.frecuencia_semanal) frecuencia_semanal = parseInt(rrssConfig.data.frecuencia_semanal);
  }
} catch(e) { /* continueOnFail — usar fallback de Config G54 */ }

const mesesMap = { '1 mes':4, '2 meses':9, '3 meses':13, '4 meses':17, '6 meses':26, '12 meses':52 };
const semanas  = mesesMap[tiempo_horizonte] || 13;
const total_ideas = semanas * frecuencia_semanal;

// Datos empresa
const empresa_nombre = emp.name              || '';
const industria      = emp.industry          || '';
const descripcion    = emp.description       || '';
const valor          = emp.value_proposition || '';
const ciudad         = emp.base_city         || '';
const web            = emp.website           || '';
const objetivo       = emp.primary_goal      || '';
const audiencia      = emp.target_market     || '';
const geografia      = emp.geography         || '';
const email          = (emp.emails||[])[0]   || '';

// Catálogo
const catalogo = prods.map(p => {
  const kw = (p.keywords||[]).join(', ');
  return `• ${p.name||''}: ${p.description||''}${kw?' ['+kw+']':''}`;
}).join('\n');

// Keywords por intención
const kwByIntencion = { local:[], comercial:[], informacional:[], transaccional:[] };
for (const k of allKw) {
  const intent = k.intencion || 'informacional';
  if (kwByIntencion[intent]) kwByIntencion[intent].push(k.keyword);
  else kwByIntencion.informacional.push(k.keyword);
}
const kwSection = `KEYWORDS EXISTENTES EN G54 (usar estas — NO inventar nuevas):
• Local/GEO:     ${kwByIntencion.local.join(' | ')         || 'N/A'}
• Comercial:     ${kwByIntencion.comercial.join(' | ')     || 'N/A'}
• Informacional: ${kwByIntencion.informacional.join(' | ') || 'N/A'}
• Transaccional: ${kwByIntencion.transaccional.join(' | ') || 'N/A'}`;

// Competidores (embebidos en el GET de empresa)
