const parsed = $('🔍 Parsear Estrategia').item.json;
const trend  = $('✅ Evaluar Verificación Tendencia').item.json;
const company_id = $('⚙️ Config G54').item.json.G54_COMPANY_ID || 1;

const ideasPlan = parsed.ideas_plan || [];
const frecSemanal = Number($('⚙️ Config G54').item.json.G54_FRECUENCIA_SEMANAL) || 3;
const generalesPorSemana = Math.max(1, frecSemanal - 1);

// Agrupar ideas por semana, tomar N-1 por semana
const semanas = {};
for (const idea of ideasPlan) {
  const s = idea.semana || 1;
  if (!semanas[s]) semanas[s] = [];
  if (semanas[s].length < generalesPorSemana) {
    semanas[s].push({
      topic:        idea.titulo || idea.topic || '',
      tipo:         idea.tipo   || 'TOFU',
      keyword:      idea.keyword || '',
      plataforma:   idea.plataforma || 'Instagram',
      semana:       s,
      dia:          idea.dia || '',
      estado:       'pendiente',
      es_tendencia: false
    });
  }
}

// Si no hay ideas del plan, crear semanas vacías para al menos poner la tendencia
if (Object.keys(semanas).length === 0) {
  semanas[1] = [];
}

// Agregar 1 idea de tendencia por semana
for (const s of Object.keys(semanas)) {
  if (trend.trend_topic) {
    semanas[s].push({
      topic:         trend.trend_topic,
      tipo:          'TOFU',
      keyword:       trend.trend_keyword || '',
      plataforma:    trend.trend_platform || 'Instagram',
      semana:        Number(s),
      dia:           'viernes',
      estado:        'pendiente',
      es_tendencia:  true,
      justificacion: trend.trend_justify || ''
    });
  }
}

const ideas = Object.values(semanas).flat();
if (ideas.length === 0) return [{ json: { skipped: true } }];

return [{ json: { company_id: Number(company_id), ideas } }];

