const titles = articles
  .filter(a => a.title && a.title !== '[Removed]')
  .slice(0, 8)
  .map((a, i) => `${i+1}. ${a.title} (${a.source?.name || ''})`);

const summary = titles.length > 0
  ? titles.join('\n')
  : 'No recent news found.';

return [{ json: {
  headlines: summary,
  count: titles.length
}}];

// Build English search query from company data
